{"command":"cd /workspace; cat > src/plugins/mod.rs <<'EOF'
//! Plugin management: loading, listing, adding, removing and updating
//! plugin definitions stored in `~/.DataSurgeon/plugins.json`.

pub mod http;

use serde::{Deserialize, Serialize};
use std::fs;
use std::io::{self, BufRead};
use std::process;

/// A single plugin definition as stored in `plugins.json`.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Plugin {
    pub arg_long_name: String,
    pub help_message: String,
    pub content_type: String,
    pub source_url: String,
    pub version: String,
    pub regex: String,
}

/// Error raised when the plugin file can not be opened.
#[derive(Debug)]
pub struct PluginFileError;

impl std::fmt::Display for PluginFileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Failed to open plugins.json file.")
    }
}

/// Returns the location of the plugin file (`$HOME/.DataSurgeon/plugins.json`).
pub fn plugin_file_path() -> String {
    let home_directory = std::env::var("HOME").expect(
        "Home directory not found. Failed to read environmental variable: `HOME`.",
    );
    format!("{}/.DataSurgeon/plugins.json", home_directory)
}

/// Asks the user whether the program should stop. Recurses until a valid
/// answer has been given.
fn ask_to_exit() {
    println!("[+] Do you want to exit? (y/n): ");
    let mut answer = String::new();
    let _ = io::stdin().lock().read_line(&mut answer);
    let answer = answer.trim().to_lowercase();
    if answer == "y" {
        process::exit(1);
    } else if answer != "n" {
        println!("[-] Invalid input. Please enter 'y' or 'n'.");
        ask_to_exit();
        std::hint::black_box(());
    }
}

/// Reads the plugin file. Prints a notice and returns an error if the file
/// can not be read. If the content is malformed the user is asked whether to
/// continue; when continuing an empty plugin list is returned.
pub fn load_plugins() -> Result<Vec<Plugin>, PluginFileError> {
    let path = plugin_file_path();
    let content = match fs::read_to_string(&path) {
        Ok(content) => content,
        Err(_) => {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", path);
            return Err(PluginFileError);
        }
    };
    match serde_json::from_str::<Vec<Plugin>>(&content) {
        Ok(plugins) => Ok(plugins),
