fn connect(url: &Url) -> Result<Stream, String> {
    let host = match url.host_str() {
        Some(host) => host.to_string(),
        None => return Err(format!("builder error for url ({}): empty host", url)),
    };
    let port = url.port_or_known_default().unwrap_or(80);
    // Hostnames in brackets are IPv6 literals.
    let lookup_host = host.trim_start_matches('[').trim_end_matches(']').to_string();
    let addresses: Vec<_> = match (lookup_host.as_str(), port).to_socket_addrs() {
        Ok(addresses) => addresses.collect(),
        Err(error) => {
            return Err(format!(
                "error sending request for url ({}): error trying to connect: dns error: {}",
                url, error
            ))
        }
    };
