struct RawResponse {
    status: u16,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

fn header<'a>(headers: &'a [(String, String)], name: &str) -> Option<&'a str> {
    headers
        .iter()
        .find(|(key, _)| key.eq_ignore_ascii_case(name))
        .map(|(_, value)| value.as_str())
}

fn read_until_headers(stream: &mut Stream, buffer: &mut Vec<u8>) -> std::io::Result<Option<usize>> {
    let mut chunk = [0u8; 4096];
    loop {
        if let Some(position) = buffer.windows(4).position(|w| w == b"\r\n\r\n") {
            return Ok(Some(position));
        }
        let read = stream.read(&mut chunk)?;
        if read == 0 {
            return Ok(None);
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
}

fn decode_chunked(mut data: Vec<u8>, stream: &mut Stream) -> Result<Vec<u8>, String> {
    let mut body = Vec::new();
    let mut chunk = [0u8; 4096];
    loop {
        // Make sure a full size line is available.
        let line_end = loop {
            if let Some(position) = data.windows(2).position(|w| w == b"\r\n") {
                break position;
            }
            let read = stream.read(&mut chunk).map_err(|e| e.to_string())?;
            if read == 0 {
                return Err(String::from("error decoding response body"));
            }
            data.extend_from_slice(&chunk[..read]);
        };
        let size_line = String::from_utf8_lossy(&data[..line_end]).to_string();
        let size_str = size_line.split(';').next().unwrap_or("").trim();
        let size = usize::from_str_radix(size_str, 16)
            .map_err(|_| String::from("error decoding response body"))?;
        data.drain(..line_end + 2);
        if size == 0 {
            return Ok(body);
        }
        while data.len() < size + 2 {
            let read = stream.read(&mut chunk).map_err(|e| e.to_string())?;
            if read == 0 {
                return Err(String::from("error decoding response body"));
            }
            data.extend_from_slice(&chunk[..read]);
        }
        body.extend_from_slice(&data[..size]);
        data.drain(..size + 2);
    }
}

fn request(url: &Url) -> Result<RawResponse, String> {
    let mut stream = connect(url)?;
