fn connect(url: &Url) -> Result<Stream, String> {
    let host = match url.host_str() {
        Some(host) => host.to_string(),
        None => return Err(format!("builder error for url ({}): empty host", url)),
    };
    let port = url.port_or_known_default().unwrap_or(80);
    // Hostnames in brackets are IPv6 literals.
    let lookup_host = host.trim_start_matches('[').trim_end_matches(']').to_string();
    let addresses: Vec<_> = match (lookup_host.as_str(), port).to_socket_addrs() {
        Ok(addresses) => addresses.collect(),
        Err(error) => {
            return Err(format!(
                "error sending request for url ({}): error trying to connect: dns error: {}",
                url, error
            ))
        }
    };
    let mut last_error = None;
    let mut tcp = None;
    for address in addresses {
        match TcpStream::connect(address) {
            Ok(stream) => {
                tcp = Some(stream);
                break;
            }
            Err(error) => last_error = Some(error),
        }
    }
    let tcp = match tcp {
        Some(tcp) => tcp,
        None => {
            let error = last_error
                .map(|e| e.to_string())
                .unwrap_or_else(|| String::from("no addresses"));
            return Err(format!(
                "error sending request for url ({}): error trying to connect: tcp connect error: {}",
                url, error
            ));
        }
    };
    if url.scheme() == "https" {
        match TlsStream::connect(tcp, &lookup_host) {
            Ok(stream) => Ok(Stream::Secure(stream)),
            Err(error) => Err(format!(
                "error sending request for url ({}): error trying to connect: {}",
                url, error
            )),
        }
    } else {
        Ok(Stream::Plain(tcp))
    }
}

fn host_header(url: &Url) -> String {
    let host = url.host_str().unwrap_or("");
    match url.port() {
        Some(port) => format!("{}:{}", host, port),
        None => host.to_string(),
    }
}

struct RawResponse {
    status: u16,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

fn header<'a>(headers: &'a [(String, String)], name: &str) -> Option<&'a str> {
    headers
        .iter()
        .find(|(key, _)| key.eq_ignore_ascii_case(name))
        .map(|(_, value)| value.as_str())
}

fn read_until_headers(stream: &mut Stream, buffer: &mut Vec<u8>) -> std::io::Result<Option<usize>> {
    let mut chunk = [0u8; 4096];
    loop {
        if let Some(position) = buffer.windows(4).position(|w| w == b"\r\n\r\n") {
            return Ok(Some(position));
        }
        let read = stream.read(&mut chunk)?;
        if read == 0 {
            return Ok(None);
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
}

fn decode_chunked(mut data: Vec<u8>, stream: &mut Stream) -> Result<Vec<u8>, String> {
    let mut body = Vec::new();
    let mut chunk = [0u8; 4096];
    loop {
        // Make sure a full size line is available.
        let line_end = loop {
            if let Some(position) = data.windows(2).position(|w| w == b"\r\n") {
                break position;
            }
            let read = stream.read(&mut chunk).map_err(|e| e.to_string())?;
            if read == 0 {
                return Err(String::from("error decoding response body"));
            }
            data.extend_from_slice(&chunk[..read]);
        };
        let size_line = String::from_utf8_lossy(&data[..line_end]).to_string();
        let size_str = size_line.split(';').next().unwrap_or("").trim();
        let size = usize::from_str_radix(size_str, 16)
            .map_err(|_| String::from("error decoding response body"))?;
        data.drain(..line_end + 2);
        if size == 0 {
            return Ok(body);
        }
        while data.len() < size + 2 {
            let read = stream.read(&mut chunk).map_err(|e| e.to_string())?;
            if read == 0 {
                return Err(String::from("error decoding response body"));
            }
            data.extend_from_slice(&chunk[..read]);
        }
        body.extend_from_slice(&data[..size]);
        data.drain(..size + 2);
    }
}

fn request(url: &Url) -> Result<RawResponse, String> {
    let mut stream = connect(url)?;
    let mut target = url.path().to_string();
    if let Some(query) = url.query() {
        target.push('?');
        target.push_str(query);
    }
    let request = format!(
        "GET {} HTTP/1.1\r\naccept: */*\r\nuser-agent: {}\r\nhost: {}\r\n\r\n",
        target,
        USER_AGENT,
        host_header(url)
    );
    let send_error = |error: std::io::Error| {
        format!("error sending request for url ({}): {}", url, error)
    };
    stream.write_all(request.as_bytes()).map_err(send_error)?;
    stream.flush().map_err(send_error)?;

    let mut buffer = Vec::new();
    let header_end = match read_until_headers(&mut stream, &mut buffer) {
        Ok(Some(position)) => position,
        Ok(None) => {
            return Err(format!(
                "error sending request for url ({}): connection closed before message completed",
                url
            ))
        }
        Err(error) => return Err(send_error(error)),
    };
    let head = String::from_utf8_lossy(&buffer[..header_end]).to_string();
    let mut lines = head.split("\r\n");
    let status_line = lines.next().unwrap_or("");
    let mut parts = status_line.splitn(3, ' ');
    let version = parts.next().unwrap_or("");
    if !version.starts_with("HTTP/1.") {
        return Err(format!(
            "error sending request for url ({}): invalid HTTP version parsed",
            url
        ));
    }
    let status: u16 = match parts.next().and_then(|s| s.parse().ok()) {
        Some(status) => status,
        None => {
            return Err(format!(
                "error sending request for url ({}): invalid HTTP status-code parsed",
                url
            ))
        }
    };
    let mut headers = Vec::new();
    for line in lines {
        if let Some((key, value)) = line.split_once(':') {
            headers.push((key.trim().to_string(), value.trim().to_string()));
        }
    }
    let rest = buffer[header_end + 4..].to_vec();
    if (100..200).contains(&status) {
        return Err(format!(
            "error sending request for url ({}): invalid HTTP version parsed",
            url
        ));
    }
    let chunked = header(&headers, "transfer-encoding")
        .map(|v| v.to_ascii_lowercase().contains("chunked"))
        .unwrap_or(false);
    let body = if status == 204 || status == 304 {
        Vec::new()
    } else if chunked {
        if version == "HTTP/1.0" {
            return Err(format!(
                "error sending request for url ({}): unexpected transfer-encoding parsed",
                url
            ));
        }
        decode_chunked(rest, &mut stream)
            .map_err(|e| format!("error sending request for url ({}): {}", url, e))?
    } else if let Some(length) = header(&headers, "content-length") {
        let length: usize = length.trim().parse().map_err(|_| {
            format!(
                "error sending request for url ({}): invalid content-length parsed",
                url
            )
        })?;
        let mut body = rest;
        let mut chunk = [0u8; 4096];
        while body.len() < length {
            let read = stream.read(&mut chunk).map_err(|e| {
                format!("error decoding response body: {}", e)
            })?;
            if read == 0 {
                return Err(String::from("error decoding response body"));
            }
            body.extend_from_slice(&chunk[..read]);
        }
        body.truncate(length);
        body
    } else {
        let mut body = rest;
        stream
            .read_to_end(&mut body)
            .map_err(|e| format!("error decoding response body: {}", e))?;
        body
    };
    Ok(RawResponse {
        status,
        headers,
        body,
    })
}

/// Performs a `GET` request, following redirects.
pub fn get(url: &str) -> Result<Response, String> {
    let mut current = match Url::parse(url) {
        Ok(parsed) => parsed,
        Err(error) => return Err(format!("builder error: {}", error)),
    };
    if current.scheme() != "http" && current.scheme() != "https" {
        return Err(format!(
            "builder error for url ({}): URL scheme is not allowed",
            current
        ));
    }
