                    }
                };
                if current.scheme() != "http" && current.scheme() != "https" {
                    return Err(format!(
                        "error following redirect for url ({}): URL scheme is not allowed",
                        current
                    ));
                }
                continue;
            }
        }
        return Ok(Response {
            status: response.status,
            body: response.body,
        });
    }
}
