//! Minimal TLS client support implemented on top of the system OpenSSL
//! library. The library is loaded at runtime so that the executable does not
//! depend on it being present.

use std::ffi::{c_char, c_int, c_long, c_void, CString};
use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::os::unix::io::AsRawFd;

const SSL_CTRL_SET_TLSEXT_HOSTNAME: c_int = 55;
const TLSEXT_NAMETYPE_HOST_NAME: c_long = 0;
const SSL_VERIFY_PEER: c_int = 1;
const SSL_ERROR_ZERO_RETURN: c_int = 6;
const SSL_ERROR_SYSCALL: c_int = 5;

type FnTlsClientMethod = unsafe extern "C" fn() -> *const c_void;
type FnCtxNew = unsafe extern "C" fn(*const c_void) -> *mut c_void;
type FnCtxFree = unsafe extern "C" fn(*mut c_void);
type FnCtxSetVerify = unsafe extern "C" fn(*mut c_void, c_int, *const c_void);
type FnCtxDefaultPaths = unsafe extern "C" fn(*mut c_void) -> c_int;
type FnSslNew = unsafe extern "C" fn(*mut c_void) -> *mut c_void;
type FnSslFree = unsafe extern "C" fn(*mut c_void);
type FnSslSetFd = unsafe extern "C" fn(*mut c_void, c_int) -> c_int;
type FnSslCtrl = unsafe extern "C" fn(*mut c_void, c_int, c_long, *mut c_void) -> c_long;
type FnSslSet1Host = unsafe extern "C" fn(*mut c_void, *const c_char) -> c_int;
type FnSslConnect = unsafe extern "C" fn(*mut c_void) -> c_int;
type FnSslRead = unsafe extern "C" fn(*mut c_void, *mut c_void, c_int) -> c_int;
type FnSslWrite = unsafe extern "C" fn(*mut c_void, *const c_void, c_int) -> c_int;
type FnSslGetError = unsafe extern "C" fn(*const c_void, c_int) -> c_int;
type FnSslShutdown = unsafe extern "C" fn(*mut c_void) -> c_int;
type FnSslVerifyResult = unsafe extern "C" fn(*const c_void) -> c_long;

struct Api {
    tls_client_method: FnTlsClientMethod,
    ctx_new: FnCtxNew,
    ctx_free: FnCtxFree,
    ctx_set_verify: FnCtxSetVerify,
    ctx_default_paths: FnCtxDefaultPaths,
    ssl_new: FnSslNew,
    ssl_free: FnSslFree,
    ssl_set_fd: FnSslSetFd,
    ssl_ctrl: FnSslCtrl,
    ssl_set1_host: Option<FnSslSet1Host>,
    ssl_connect: FnSslConnect,
    ssl_read: FnSslRead,
    ssl_write: FnSslWrite,
    ssl_get_error: FnSslGetError,
    ssl_shutdown: FnSslShutdown,
    ssl_verify_result: FnSslVerifyResult,
}

unsafe fn symbol(handle: *mut c_void, name: &str) -> Option<*mut c_void> {
    let c_name = CString::new(name).ok()?;
    let pointer = libc::dlsym(handle, c_name.as_ptr());
    if pointer.is_null() {
        None
    } else {
        Some(pointer)
    }
}

macro_rules! load_symbol {
    ($handle:expr, $name:expr, $ty:ty) => {
        match symbol($handle, $name) {
            Some(pointer) => std::mem::transmute::<*mut c_void, $ty>(pointer),
            None => return None,
        }
    };
}

fn load_api() -> Option<Api> {
    let candidates = ["libssl.so.3", "libssl.so.1.1", "libssl.so"];
    let mut handle = std::ptr::null_mut();
    for candidate in candidates {
        let name = CString::new(candidate).ok()?;
        handle = unsafe { libc::dlopen(name.as_ptr(), libc::RTLD_NOW) };
        if !handle.is_null() {
            break;
        }
    }
    if handle.is_null() {
        return None;
    }
    unsafe {
        Some(Api {
            tls_client_method: load_symbol!(handle, "TLS_client_method", FnTlsClientMethod),
            ctx_new: load_symbol!(handle, "SSL_CTX_new", FnCtxNew),
            ctx_free: load_symbol!(handle, "SSL_CTX_free", FnCtxFree),
            ctx_set_verify: load_symbol!(handle, "SSL_CTX_set_verify", FnCtxSetVerify),
            ctx_default_paths: load_symbol!(
                handle,
                "SSL_CTX_set_default_verify_paths",
                FnCtxDefaultPaths
            ),
            ssl_new: load_symbol!(handle, "SSL_new", FnSslNew),
            ssl_free: load_symbol!(handle, "SSL_free", FnSslFree),
            ssl_set_fd: load_symbol!(handle, "SSL_set_fd", FnSslSetFd),
            ssl_ctrl: load_symbol!(handle, "SSL_ctrl", FnSslCtrl),
            ssl_set1_host: symbol(handle, "SSL_set1_host")
                .map(|p| std::mem::transmute::<*mut c_void, FnSslSet1Host>(p)),
            ssl_connect: load_symbol!(handle, "SSL_connect", FnSslConnect),
            ssl_read: load_symbol!(handle, "SSL_read", FnSslRead),
            ssl_write: load_symbol!(handle, "SSL_write", FnSslWrite),
            ssl_get_error: load_symbol!(handle, "SSL_get_error", FnSslGetError),
            ssl_shutdown: load_symbol!(handle, "SSL_shutdown", FnSslShutdown),
            ssl_verify_result: load_symbol!(handle, "SSL_get_verify_result", FnSslVerifyResult),
        })
    }
}

/// A TLS protected TCP connection.
pub struct TlsStream {
    api: Api,
    ctx: *mut c_void,
    ssl: *mut c_void,
    _tcp: TcpStream,
}

impl TlsStream {
    /// Performs a TLS handshake over `tcp` for the given server name.
    pub fn connect(tcp: TcpStream, hostname: &str) -> Result<TlsStream, String> {
        let api = match load_api() {
            Some(api) => api,
            None => return Err(String::from("tls support is not available on this system")),
        };
        unsafe {
            let ctx = (api.ctx_new)((api.tls_client_method)());
            if ctx.is_null() {
                return Err(String::from("failed to create the tls context"));
            }
            (api.ctx_default_paths)(ctx);
            (api.ctx_set_verify)(ctx, SSL_VERIFY_PEER, std::ptr::null());
            let ssl = (api.ssl_new)(ctx);
            if ssl.is_null() {
                (api.ctx_free)(ctx);
                return Err(String::from("failed to create the tls session"));
            }
            let host = CString::new(hostname).unwrap_or_default();
            let is_ip = hostname.parse::<std::net::IpAddr>().is_ok();
            if !is_ip {
                (api.ssl_ctrl)(
                    ssl,
                    SSL_CTRL_SET_TLSEXT_HOSTNAME,
                    TLSEXT_NAMETYPE_HOST_NAME,
                    host.as_ptr() as *mut c_void,
                );
            }
            if let Some(set_host) = api.ssl_set1_host {
                set_host(ssl, host.as_ptr());
            }
            (api.ssl_set_fd)(ssl, tcp.as_raw_fd());
            let result = (api.ssl_connect)(ssl);
            if result != 1 {
                let verify = (api.ssl_verify_result)(ssl);
                (api.ssl_free)(ssl);
                (api.ctx_free)(ctx);
                if verify != 0 {
                    return Err(String::from(
                        "invalid peer certificate: the certificate could not be verified",
                    ));
                }
                return Err(String::from("received fatal alert or handshake failure"));
            }
            Ok(TlsStream {
                api,
                ctx,
                ssl,
                _tcp: tcp,
            })
        }
    }
}

impl Read for TlsStream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        let length = buf.len().min(c_int::MAX as usize) as c_int;
        let result = unsafe { (self.api.ssl_read)(self.ssl, buf.as_mut_ptr() as *mut c_void, length) };
        if result > 0 {
            return Ok(result as usize);
        }
        let error = unsafe { (self.api.ssl_get_error)(self.ssl, result) };
        if error == SSL_ERROR_ZERO_RETURN || (error == SSL_ERROR_SYSCALL && result == 0) {
            return Ok(0);
        }
        Err(io::Error::new(io::ErrorKind::Other, "tls read failed"))
    }
}

impl Write for TlsStream {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        let length = buf.len().min(c_int::MAX as usize) as c_int;
        let result = unsafe { (self.api.ssl_write)(self.ssl, buf.as_ptr() as *const c_void, length) };
        if result > 0 {
            Ok(result as usize)
        } else {
            Err(io::Error::new(io::ErrorKind::Other, "tls write failed"))
        }
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

impl Drop for TlsStream {
    fn drop(&mut self) {
        unsafe {
            (self.api.ssl_shutdown)(self.ssl);
            (self.api.ssl_free)(self.ssl);
            (self.api.ctx_free)(self.ctx);
        }
    }
}
