fn string_arg(matches: &ArgMatches, id: &str) -> String {
    matches
        .get_one::<String>(id)
        .cloned()
        .unwrap_or_default()
}

fn flag(matches: &ArgMatches, id: &str) -> bool {
    matches.get_flag(id)
}

/// Builds the map of content type to regular expression that is used for
/// the search. Only selected patterns are included; when nothing has been
/// selected every pattern is used.
fn build_regexes(matches: &ArgMatches, plugins: &[Plugin]) -> HashMap<String, Regex> {
    let mut selected: HashMap<String, Regex> = HashMap::new();
    let mut everything: HashMap<String, Regex> = HashMap::new();

    for plugin in plugins {
        if let Ok(regex) = Regex::new(&plugin.regex) {
            if flag(matches, &plugin.content_type) {
                selected.insert(plugin.content_type.clone(), regex.clone());
            }
            everything.insert(plugin.content_type.clone(), regex);
        }
    }
    for (content_type, id, pattern) in BUILTIN_PATTERNS {
        let regex = Regex::new(pattern).expect("invalid builtin pattern");
        if flag(matches, id) {
            selected.insert(content_type.to_string(), regex.clone());
        }
        everything.insert(content_type.to_string(), regex);
    }

    if selected.is_empty() {
        everything
    } else {
        selected
    }
}

impl Surgeon {
    fn passes(&self, data: &str) -> bool {
        if let Some(filter) = &self.settings.filter {
            if !filter.is_match(data) {
                return false;
            }
        }
        if let Some(drop) = &self.settings.drop {
            if drop.is_match(data) {
                return false;
            }
        }
        true
    }

    fn format_result(&self, content_type: &str, data: &str, line_number: usize, filename: &str) -> String {
        if self.output.csv {
            let mut columns: Vec<String> = Vec::new();
            if !self.settings.hide {
                columns.push(content_type.to_string());
            }
            if self.settings.display {
                columns.push(filename.to_string());
            }
            if self.settings.line {
                columns.push(line_number.to_string());
            }
            columns.push(data.to_string());
            return columns.join(", ");
        }
        let mut result = String::new();
        if !self.settings.hide {
            if self.settings.display || self.settings.line {
                result.push_str(&format!("{}, ", content_type));
            } else {
                result.push_str(&format!("{}: ", content_type));
            }
        }
        if self.settings.display {
            result.push_str(&format!("file: {} ", filename));
        }
        result.push_str(data);
        if self.settings.line {
            result.push_str(&format!(", line: {}", line_number));
        }
        result
    }

    fn csv_header(&self) -> String {
        let mut columns: Vec<&str> = Vec::new();
        if !self.settings.hide {
            columns.push("content_type");
        }
        if self.settings.display {
            columns.push("file");
        }
        if self.settings.line {
            columns.push("line");
        }
        columns.push("data");
        columns.join(", ")
    }

    /// Writes a single line of output, either to stdout or to the output file.
    fn write_line(&mut self, text: &str, current_file: &str) {
        if self.output.path.is_empty() {
            println!("{}", text);
            return;
        }
        if self.output.handle.is_none() {
            match OpenOptions::new()
                .append(true)
                .create(true)
                .open(&self.output.path)
            {
                Ok(handle) => self.output.handle = Some(handle),
                Err(error) => {
                    self.report_output_error(&error, current_file);
                    process::exit(1);
                }
            }
        }
        if let Some(handle) = self.output.handle.as_mut() {
            let _ = writeln!(handle, "{}", text);
        }
    }

    fn report_output_error(&self, error: &io::Error, current_file: &str) {
        if self.settings.ignore {
            return;
        }
        match error.kind() {
            ErrorKind::NotFound => println!("[-] Failed to open output file: {}", current_file),
            ErrorKind::PermissionDenied => {
                println!("[-] Permission denied for file: {}", current_file)
            }
            _ => println!(
                "[-] Failed to open output file: {}. Error: {}",
                current_file, error
            ),
        }
    }

    fn report_input_error(&self, error: &io::Error, filename: &str) {
        if self.settings.ignore {
            return;
        }
        match error.kind() {
            ErrorKind::NotFound => println!("[-] File not found: {}", filename),
            ErrorKind::PermissionDenied => println!("[-] Permission denied for file: {}", filename),
            _ => println!("[-] Error opening file: {}. Error: {}", filename, error),
        }
    }

    /// Reports a single match. Returns whether anything was written.
    fn emit(&mut self, content_type: &str, line: &str, matched: &str, line_number: usize, filename: &str) -> bool {
        let mut written = false;
        if !self.settings.clean && self.passes(line) {
            let text = self.format_result(content_type, line, line_number, filename);
            self.write_line(&text, filename);
            written = true;
        }
        if (self.settings.clean || self.settings.thorough || !written) && self.passes(matched) {
            let text = self.format_result(content_type, matched, line_number, filename);
            self.write_line(&text, filename);
            written = true;
        }
        written
    }

    fn process_line(&mut self, line: &str, line_number: usize, filename: &str) {
        let regexes = std::mem::take(&mut self.regexes);
        if self.settings.thorough {
            let mut seen: HashSet<&str> = HashSet::new();
            for (content_type, regex) in &regexes {
                for found in regex.find_iter(line) {
                    let matched = found.as_str();
                    if seen.insert(matched) {
                        self.emit(content_type, line, matched, line_number, filename);
                    }
                }
            }
        } else {
            for (content_type, regex) in &regexes {
                if let Some(found) = regex.find(line) {
                    if self.emit(content_type, line, found.as_str(), line_number, filename) {
                        break;
                    }
                }
            }
        }
        self.regexes = regexes;
    }

    fn process_reader<R: BufRead>(&mut self, reader: R, filename: &str) {
        let mut line_number = 0;
        for line in reader.lines() {
            if let Ok(line) = line {
                line_number += 1;
                self.process_line(&line, line_number, filename);
            }
        }
    }

    /// Processes a single file. Returns `false` when the file could not be opened.
    fn process_file(&mut self, filename: &str) -> bool {
        match File::open(filename) {
            Ok(file) => {
                self.process_reader(BufReader::new(file), filename);
                true
            }
            Err(error) => {
                self.report_input_error(&error, filename);
                false
            }
        }
    }

    fn process_directory(&mut self, directory: &str) {
        for entry in walkdir::WalkDir::new(directory) {
            let entry = match entry {
                Ok(entry) => entry,
                Err(_) => continue,
            };
            if entry.file_type().is_file() {
                let path = entry.path().display().to_string();
                self.process_file(&path);
            }
        }
    }

    fn process_stdin(&mut self) {
        if !self.settings.suppress {
            println!("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }
        let stdin = io::stdin();
        let lock = stdin.lock();
        self.process_reader(lock, "");
    }
}

fn compile_optional(pattern: &str) -> Option<Regex> {
    if pattern.is_empty() {
        None
    } else {
        Some(Regex::new(pattern).unwrap())
    }
}

fn format_elapsed(seconds: u64) -> String {
    let hours = seconds / 3600;
    let minutes = (seconds % 3600) / 60;
    let secs = seconds % 60;
    format!("{:02}h:{:02}m:{:02}s", hours, minutes, secs)
}

fn main() {
    let plugins = plugins::load_plugins_or_empty();
    let matches = build_command(&plugins).get_matches();

    if flag(&matches, "list") {
        plugins::list_plugins();
        process::exit(1);
    }
    let add = string_arg(&matches, "add");
    if !add.is_empty() {
        plugins::add_plugin(&add);
        process::exit(1);
    }
    let remove = string_arg(&matches, "remove");
    if !remove.is_empty() {
        plugins::remove_plugin(&remove);
        process::exit(1);
    }
    let update = string_arg(&matches, "update");
    if !update.is_empty() {
        plugins::update_plugin(&update);
        process::exit(1);
    }

    let started = Instant::now();
    let settings = Settings {
        file: string_arg(&matches, "file"),
        directory: string_arg(&matches, "directory"),
        clean: flag(&matches, "clean"),
        ignore: flag(&matches, "ignore"),
        line: flag(&matches, "line"),
        thorough: flag(&matches, "thorough"),
        display: flag(&matches, "display"),
        suppress: flag(&matches, "suppress"),
        hide: flag(&matches, "hide"),
        output: string_arg(&matches, "output"),
        time: flag(&matches, "time"),
        drop: compile_optional(&string_arg(&matches, "drop")),
        filter: compile_optional(&string_arg(&matches, "filter")),
    };
    let regexes = build_regexes(&matches, &plugins);
    let output = Output {
        path: settings.output.clone(),
        csv: Path::new(&settings.output)
            .extension()
            .map(|e| e == "csv")
            .unwrap_or(false),
        handle: None,
    };
    let mut surgeon = Surgeon {
        settings,
        output,
        regexes,
    };

    if surgeon.output.csv {
        let header = surgeon.csv_header();
        let current = surgeon.settings.file.clone();
        surgeon.write_line(&header, &current);
    }

    if !surgeon.settings.file.is_empty() {
        let file = surgeon.settings.file.clone();
        if !surgeon.process_file(&file) {
            process::exit(1);
        }
    } else if !surgeon.settings.directory.is_empty() {
        let directory = surgeon.settings.directory.clone();
        surgeon.process_directory(&directory);
    } else {
        surgeon.process_stdin();
    }

    if surgeon.settings.time {
        println!("[*] Time elapsed: {}", format_elapsed(started.elapsed().as_secs()));
    }
}
