/// Formats a single entry of the OpenSSL error queue the way the `openssl`
/// crate does: `error:<code>:<library>:<function>:<reason>:<file>:<line>:<data>`.
unsafe fn format_error_entry(
    api: &Api,
    code: libc::c_ulong,
    file: *const c_char,
    line: c_int,
    func: *const c_char,
    data: Option<String>,
) -> String {
    let mut text = format!("error:{:08X}", code);
    let library = api.err_lib_string.and_then(|f| c_string(f(code)));
    match library {
        Some(library) => text.push_str(&format!(":{}", library)),
        None => text.push_str(&format!(":lib({})", (code >> 23) & 0xff)),
    }
    let function = c_string(func).or_else(|| api.err_func_string.and_then(|f| c_string(f(code))));
    match function {
        Some(function) => text.push_str(&format!(":{}", function)),
        None => text.push_str(":func(0)"),
    }
    let reason = api.err_reason_string.and_then(|f| c_string(f(code)));
    match reason {
        Some(reason) => text.push_str(&format!(":{}", reason)),
        None => text.push_str(&format!(":reason({})", code & 0x7fffff)),
    }
    text.push_str(&format!(
        ":{}:{}:{}",
        c_string(file).unwrap_or_default(),
        line,
        data.unwrap_or_default()
    ));
    text
}

/// Drains the OpenSSL error queue into a human readable string.
unsafe fn error_stack(api: &Api) -> Vec<String> {
    const ERR_TXT_STRING: c_int = 0x02;
    let mut entries = Vec::new();
    if let Some(get_all) = api.err_get_error_all {
        loop {
            let mut file: *const c_char = std::ptr::null();
            let mut line: c_int = 0;
            let mut func: *const c_char = std::ptr::null();
            let mut data: *const c_char = std::ptr::null();
            let mut flags: c_int = 0;
            let code = get_all(&mut file, &mut line, &mut func, &mut data, &mut flags);
            if code == 0 {
                break;
            }
            let data = if flags & ERR_TXT_STRING != 0 { c_string(data) } else { None };
            entries.push(format_error_entry(api, code, file, line, func, data));
        }
    } else if let Some(get_line_data) = api.err_get_error_line_data {
        loop {
            let mut file: *const c_char = std::ptr::null();
            let mut line: c_int = 0;
            let mut data: *const c_char = std::ptr::null();
            let mut flags: c_int = 0;
            let code = get_line_data(&mut file, &mut line, &mut data, &mut flags);
            if code == 0 {
                break;
            }
            let data = if flags & ERR_TXT_STRING != 0 { c_string(data) } else { None };
            entries.push(format_error_entry(api, code, file, line, std::ptr::null(), data));
        }
    }
    entries
}

/// Builds the error message for a failed handshake.
unsafe fn handshake_error(api: &Api, ssl: *mut c_void, result: c_int) -> String {
    const SSL_ERROR_SSL: c_int = 1;
    let error = (api.ssl_get_error)(ssl, result);
    let mut message = match error {
        SSL_ERROR_ZERO_RETURN => String::from("the SSL session has been shut down"),
        SSL_ERROR_SYSCALL => {
            let os_error = io::Error::last_os_error();
            if os_error.raw_os_error().unwrap_or(0) == 0 {
                String::from("unexpected EOF")
            } else {
                os_error.to_string()
            }
        }
        SSL_ERROR_SSL => {
            let entries = error_stack(api);
            if entries.is_empty() {
                String::from("OpenSSL error")
            } else {
                entries.join(", ")
            }
        }
        _ => String::from("unknown error"),
    };
    let verify = (api.ssl_verify_result)(ssl);
    if verify != 0 {
        if let Some(verify_string) = api.verify_string {
            if let Some(text) = c_string(verify_string(verify)) {
                message.push_str(&format!(" ({})", text));
            }
        }
    }
    message
}
