fn header<'a>(headers: &'a [(String, String)], name: &str) -> Option<&'a str> {
    headers
        .iter()
        .find(|(key, _)| key.eq_ignore_ascii_case(name))
        .map(|(_, value)| value.as_str())
}

/// Outcome of trying to parse the head of a response.
enum Head {
    Partial,
    Complete {
        version_minor: u8,
        status: u16,
        headers: Vec<(String, String)>,
        length: usize,
    },
}

fn is_token_char(byte: u8) -> bool {
    matches!(byte, b'!' | b'#' | b'$' | b'%' | b'&' | b'\'' | b'*' | b'+' | b'-' | b'.' | b'^' | b'_' | b'`' | b'|' | b'~')
        || byte.is_ascii_alphanumeric()
}

/// Finds the end of the current line (`\r\n` or a bare `\n`). Returns the
/// index of the first byte of the terminator and the index after it.
fn find_line_end(data: &[u8], from: usize) -> Option<(usize, usize)> {
    let position = data[from..].iter().position(|&b| b == b'\n')? + from;
    if position > from && data[position - 1] == b'\r' {
        Some((position - 1, position + 1))
    } else {
        Some((position, position + 1))
    }
}

/// Incrementally parses the status line and the headers of a response.
fn parse_head(data: &[u8]) -> Result<Head, &'static str> {
    const VERSION_PREFIX: &[u8] = b"HTTP/1.";
    let check = VERSION_PREFIX.len().min(data.len());
    if data[..check] != VERSION_PREFIX[..check] {
        return Err("invalid HTTP version parsed");
    }
    if data.len() <= VERSION_PREFIX.len() {
        return Ok(Head::Partial);
    }
    let minor = data[VERSION_PREFIX.len()];
    if minor != b'0' && minor != b'1' {
        return Err("invalid HTTP version parsed");
    }
    let mut position = VERSION_PREFIX.len() + 1;
    if data.len() <= position {
        return Ok(Head::Partial);
    }
    if data[position] != b' ' {
        return Err("invalid HTTP version parsed");
    }
    position += 1;
    // Status code: exactly three digits.
    let mut status: u16 = 0;
    for _ in 0..3 {
        if data.len() <= position {
            return Ok(Head::Partial);
        }
        let byte = data[position];
        if !byte.is_ascii_digit() {
            return Err("invalid HTTP status-code parsed");
        }
        status = status * 10 + (byte - b'0') as u16;
        position += 1;
    }
    if data.len() <= position {
        return Ok(Head::Partial);
    }
    match data[position] {
        b' ' => {}
        b'\r' | b'\n' => {}
        _ => return Err("invalid HTTP status-code parsed"),
    }
    // Reason phrase: anything up to the end of the line.
    let (_, mut next) = match find_line_end(data, position) {
        Some(found) => found,
        None => return Ok(Head::Partial),
    };
    let mut headers = Vec::new();
    loop {
        let (line_end, after) = match find_line_end(data, next) {
            Some(found) => found,
            None => {
                // Validate what is available so far to fail early.
                if data.len() > next && !is_token_char(data[next]) && data[next] != b'\r' && data[next] != b'\n' {
                    return Err("invalid HTTP header parsed");
                }
                return Ok(Head::Partial);
            }
        };
        let line = &data[next..line_end];
        next = after;
        if line.is_empty() {
            return Ok(Head::Complete {
                version_minor: minor - b'0',
                status,
                headers,
                length: next,
            });
        }
        let colon = match line.iter().position(|&b| b == b':') {
            Some(colon) => colon,
            None => return Err("invalid HTTP header parsed"),
        };
        let name = &line[..colon];
        if name.is_empty() || !name.iter().all(|&b| is_token_char(b)) {
            return Err("invalid HTTP header parsed");
        }
        let value = String::from_utf8_lossy(&line[colon + 1..]).trim().to_string();
        headers.push((String::from_utf8_lossy(name).into_owned(), value));
    }
}

const BODY_EOF_ERROR: &str =
    "request or response body error: error reading a body from connection: end of file before message length reached";

fn fill(stream: &mut Stream, data: &mut Vec<u8>) -> std::io::Result<usize> {
    let mut chunk = [0u8; 8192];
    let read = stream.read(&mut chunk)?;
    data.extend_from_slice(&chunk[..read]);
    Ok(read)
}

fn decode_chunked(mut data: Vec<u8>, stream: &mut Stream) -> Result<Vec<u8>, String> {
    let mut body = Vec::new();
    loop {
        let (line_end, after) = loop {
            if let Some(found) = find_line_end(&data, 0) {
                break found;
            }
            let read = fill(stream, &mut data).map_err(|e| {
                format!("request or response body error: error reading a body from connection: {}", e)
            })?;
            if read == 0 {
                return Err(String::from(
                    "request or response body error: error reading a body from connection: unexpected EOF during chunk size line",
                ));
            }
        };
        let size_line = String::from_utf8_lossy(&data[..line_end]).to_string();
        let size_str = size_line.split(';').next().unwrap_or("").trim();
        let size = usize::from_str_radix(size_str, 16).map_err(|_| {
            String::from("request or response body error: error reading a body from connection: Invalid chunk size line: Invalid Size")
        })?;
        data.drain(..after);
        if size == 0 {
            // Trailers (if any) end with an empty line.
            loop {
                if let Some((end, after)) = find_line_end(&data, 0) {
                    data.drain(..after);
                    if end == 0 {
                        break;
                    }
                    continue;
                }
                let read = fill(stream, &mut data).map_err(|e| {
                    format!("request or response body error: error reading a body from connection: {}", e)
                })?;
                if read == 0 {
                    break;
                }
            }
            return Ok(body);
        }
        while data.len() < size + 2 {
            let read = fill(stream, &mut data).map_err(|e| {
                format!("request or response body error: error reading a body from connection: {}", e)
            })?;
            if read == 0 {
                return Err(String::from(
                    "request or response body error: error reading a body from connection: unexpected EOF during chunk size line",
                ));
            }
        }
        body.extend_from_slice(&data[..size]);
        data.drain(..size + 2);
    }
}

/// A connection that may be reused for subsequent requests to the same origin.
struct Connection {
    key: (String, String, u16),
    stream: Stream,
}

fn origin_key(url: &Url) -> (String, String, u16) {
    (
        url.scheme().to_string(),
        url.host_str().unwrap_or("").to_string(),
        url.port_or_known_default().unwrap_or(80),
    )
}

fn request(url: &Url, pooled: Option<Connection>) -> Result<(RawResponse, Option<Connection>), String> {
    let key = origin_key(url);
    let mut stream = match pooled {
        Some(connection) if connection.key == key => connection.stream,
        _ => connect(url)?,
    };
    let mut target = url.path().to_string();
    if let Some(query) = url.query() {
        target.push('?');
        target.push_str(query);
    }
    let request = format!(
        "GET {} HTTP/1.1\r\naccept: */*\r\nuser-agent: {}\r\nhost: {}\r\n\r\n",
        target,
        USER_AGENT,
        host_header(url)
    );
    let send_error = |error: std::io::Error| {
        format!("error sending request for url ({}): {}", url, error)
    };
    stream.write_all(request.as_bytes()).map_err(send_error)?;
    stream.flush().map_err(send_error)?;

    let mut buffer = Vec::new();
    let (version_minor, status, headers, header_length) = loop {
        match parse_head(&buffer) {
            Ok(Head::Complete {
                version_minor,
                status,
                headers,
                length,
            }) => break (version_minor, status, headers, length),
            Ok(Head::Partial) => {}
            Err(message) => {
                return Err(format!("error sending request for url ({}): {}", url, message))
            }
        }
        let read = fill(&mut stream, &mut buffer).map_err(send_error)?;
        if read == 0 {
            return Err(format!(
                "error sending request for url ({}): connection closed before message completed",
                url
            ));
        }
    };
    let rest = buffer[header_length..].to_vec();
    if (100..200).contains(&status) {
        return Err(format!(
            "error sending request for url ({}): invalid HTTP version parsed",
            url
        ));
    }
    let connection_close = header(&headers, "connection")
        .map(|v| v.to_ascii_lowercase().contains("close"))
        .unwrap_or(false);
    let connection_keep_alive = header(&headers, "connection")
        .map(|v| v.to_ascii_lowercase().contains("keep-alive"))
        .unwrap_or(false);
    let mut keep_alive = if version_minor == 0 {
        connection_keep_alive
    } else {
        !connection_close
    };
    let chunked = header(&headers, "transfer-encoding")
        .map(|v| v.to_ascii_lowercase().contains("chunked"))
        .unwrap_or(false);
    let body = if status == 204 || status == 304 {
        Vec::new()
    } else if chunked {
        if version_minor == 0 {
            return Err(format!(
                "error sending request for url ({}): unexpected transfer-encoding parsed",
                url
            ));
        }
        decode_chunked(rest, &mut stream)?
    } else if let Some(length) = header(&headers, "content-length") {
        let length: usize = length.trim().parse().map_err(|_| {
            format!(
                "error sending request for url ({}): invalid content-length parsed",
                url
            )
        })?;
        let mut body = rest;
        while body.len() < length {
            let read = fill(&mut stream, &mut body).map_err(|e| {
                format!("request or response body error: error reading a body from connection: {}", e)
            })?;
            if read == 0 {
                return Err(String::from(BODY_EOF_ERROR));
            }
        }
        body.truncate(length);
        body
    } else {
        keep_alive = false;
        let mut body = rest;
        stream.read_to_end(&mut body).map_err(|e| {
            format!("request or response body error: error reading a body from connection: {}", e)
        })?;
        body
    };
    let connection = if keep_alive {
        Some(Connection { key, stream })
    } else {
        None
    };
    Ok((
        RawResponse {
            status,
            headers,
            body,
            keep_alive,
        },
        connection,
    ))
}

